import java.io.File

private class Settings {
    var snap=1;
    var fillHoles=0;
    var merge=true;
    var degenerate=true;
    var duplicates=true;
    var orient=true;
    var outward=true;
    var keepUnused=true;
    var sections=listOf("summary","components");
    val queries=mutableListOf<List<String>>()
}
private fun settings(): Settings {
    val s=Settings();
    for(line in File("input/params.txt").readLines(Charsets.US_ASCII)) {
        if(line.isEmpty()||line.startsWith("#"))continue;
        val w=line.split(' ');
        when(w[0]) {
            "snap"->s.snap=w[1].toInt();
            "fill_holes"->s.fillHoles=w[1].toInt();
            "merge"->s.merge=w[1]=="on";
            "degenerate"->s.degenerate=w[1]=="on";
            "duplicates"->s.duplicates=w[1]=="on";
            "orient"->s.orient=w[1]=="on";
            "outward"->s.outward=w[1]=="on";
            "keep_unused"->s.keepUnused=w[1]=="on";
            "sections"->s.sections=w.drop(1);
            "query"->s.queries+=w.drop(1)
        }
    };
    return s
}
private fun yes(b: Boolean)=if(b)"yes" else "no"
private fun listing(values: Iterable<*>)=values.toList().let {
    if(it.isEmpty())"-" else it.joinToString(" ")
}
private class Description(val c: Topology.Component) {
    var closed=false;
    var manifold=false;
    var consistent=false;
    var solid=false;
    var orientable=false;
    var loops=0;
    var euler=0;
    var genus: Int?=null;
    var crosscaps: Int?=null;
    var volume=0L;
    var area=0.0;
    var normal=Measure.Vec(0,0,0);
    var bbox=LongArray(6);
    var centroid="-";
    val inside=mutableListOf<Int>();
    val shapes=mutableMapOf<String,Int>();
    val angles=mutableMapOf<String,Int>();
    var edgeMin=Long.MAX_VALUE;
    var edgeMax=0L;
    var valenceMin=Int.MAX_VALUE;
    var valenceMax=0
}
private class Analysis(val source: ObjIo.Model,val settings: Settings) {
    val changes=mutableListOf<Repair.Snap>();
    val removed=mutableListOf<Repair.Removed>();
    val snapped=Repair.snap(source.vertices,settings.snap,changes);
    val representatives=Repair.representatives(snapped,settings.merge);
    val triangles=Repair.split(source.polygons);
    val faces=Repair.clean(triangles,snapped,representatives,settings.degenerate,settings.duplicates,removed);
    val points=mutableListOf(Measure.Vec(0,0,0));
    val renumber=sortedMapOf<Int,Int>();
    val merged=sortedMapOf<Int,MutableList<Int>>();
    lateinit var before: Topology.Mesh;
    lateinit var mesh: Topology.Mesh;
    var inconsistentBefore=listOf<Topology.Edge>();
    var inconsistentAfter=listOf<Topology.Edge>();
    var loops=listOf<Topology.Loop>();
    val components=mutableListOf<Description>();
    val initial=faces.size;
    var added=0;
    var flipped=0;
    var outward=0;
    val nonplanar=mutableSetOf<Int>();
    val groups=mutableListOf<String>()
}
private fun increment(m: MutableMap<String,Int>,key: String) {
    m[key]=m.getOrDefault(key,0)+1
}
private fun shape(e: Topology.Edge,a: Analysis): String {
    val ids=a.mesh.edges.getValue(e);
    if(ids.size!=2)return "-";
    val f=a.faces[ids[0]-1];
    val g=a.faces[ids[1]-1];
    if(Orientation.directed(f,e.a,e.b)==Orientation.directed(g,e.a,e.b))return "inconsistent";
    val third=g.v.first {
        it!=e.a&&it!=e.b
    };
    val signed=Measure.dot(Measure.subtract(a.points[third],a.points[f.v[0]]),Measure.normal(f,a.points));
    return if(signed<0)"convex" else if(signed>0)"concave" else "flat"
}
private fun nonplanar(p: ObjIo.Polygon,points: List<Measure.Vec>): Boolean {
    val first=points[p.v[0]];
    var n=Measure.Vec(0,0,0);
    for(i in 1 until p.v.size-1)n=Measure.add(n,Measure.cross(Measure.subtract(points[p.v[i]],first),Measure.subtract(points[p.v[i+1]],first)));
    return p.v.any {
        Measure.dot(Measure.subtract(points[it],first),n)!=0L
    }
}
private fun analyze(source: ObjIo.Model,s: Settings): Analysis {
    val a=Analysis(source,s);
    val present=if(s.keepUnused)(1 until a.representatives.size).filter {
        a.representatives[it]==it
    }.toSortedSet() else a.faces.flatMap {
        it.v.toList()
    }.toSortedSet();
    for(v in present) {
        a.renumber[v]=a.points.size;
        a.points+=a.snapped[v]
    };
    for(f in a.faces)for(k in 0..2)f.v[k]=a.renumber.getValue(f.v[k]);
    val original=a.faces.map {
        it.v.copyOf()
    };
    a.before=Topology.analyze(a.faces);
    a.inconsistentBefore=Orientation.inconsistent(a.faces,a.before.edges);
    if(s.orient)Orientation.repair(a.faces,a.before.edges);
    a.inconsistentAfter=Orientation.inconsistent(a.faces,a.before.edges);
    a.loops=Topology.loops(a.faces,a.before);
    val permitted=a.before.components.filter {
        it.nonmanifold.isEmpty()&&it.edges.none {
            e->e in a.inconsistentAfter
        }
    }.map {
        it.number
    }.toSet();
    a.added=Repair.fill(a.faces,a.loops,s.fillHoles,permitted);
    a.mesh=Topology.analyze(a.faces);
    val inconsistent=Orientation.inconsistent(a.faces,a.mesh.edges)
    for(c in a.mesh.components) {
        val d=Description(c);
        d.closed=c.boundary.isEmpty();
        d.manifold=c.nonmanifold.isEmpty()&&c.nonmanifoldVertices.isEmpty();
        d.consistent=c.edges.none {
            it in inconsistent
        };
        d.solid=d.closed&&d.manifold&&d.consistent;
        a.components+=d
    }
    for(d in a.components)if(d.solid)for(other in a.components)if(other!==d&&other.solid) {
        val vertex=d.c.vertices.firstOrNull {
            it !in other.c.vertices
        };
        if(vertex!=null&&Measure.winding(other.c.faces,a.faces,a.points,a.points[vertex])!=0)d.inside+=other.c.number
    }
    for(d in a.components)if(d.solid&&s.outward) {
        val v=Measure.volume(d.c.faces,a.faces,a.points);
        if(v!=0L&&((d.inside.size%2==0&&v<0)||(d.inside.size%2==1&&v>0))) {
            for(i in d.c.faces)Orientation.flip(a.faces[i-1]);
            a.outward++
        }
    }
    a.flipped=(0 until a.initial).count {
        !original[it].contentEquals(a.faces[it].v)
    };
    val orientable=Orientation.orientable(a.faces,a.mesh);
    val loopCount=Topology.loops(a.faces,a.mesh).groupingBy {
        it.component
    }.eachCount()
    for(d in a.components) {
        val c=d.c;
        d.orientable=orientable[c.number];
        d.loops=loopCount.getOrDefault(c.number,0);
        d.euler=c.vertices.size-c.edges.size+c.faces.size;
        if(d.manifold) {
            if(d.orientable)d.genus=Math.floorDiv(2-d.euler-d.loops,2) else d.crosscaps=2-d.euler-d.loops
        };
        d.volume=Measure.volume(c.faces,a.faces,a.points);
        d.area=Measure.area(c.faces.map {
            a.faces[it-1]
        },a.points);
        for(i in c.faces) {
            val f=a.faces[i-1];
            d.normal=Measure.add(d.normal,Measure.normal(f,a.points));
            increment(d.angles,Measure.angle(f,a.points))
        };
        d.bbox=Measure.bbox(c.vertices,a.points);
        if(d.solid&&d.volume!=0L)d.centroid=Measure.centroid(c.faces,a.faces,a.points,d.volume);
        val degree=mutableMapOf<Int,Int>();
        for(e in c.edges) {
            increment(d.shapes,shape(e,a));
            val length=Measure.length(e,a.points);
            d.edgeMin=minOf(d.edgeMin,length);
            d.edgeMax=maxOf(d.edgeMax,length);
            degree[e.a]=degree.getOrDefault(e.a,0)+1;
            degree[e.b]=degree.getOrDefault(e.b,0)+1
        };
        d.valenceMin=degree.values.min();
        d.valenceMax=degree.values.max()
    }
    for(p in source.polygons) {
        if(nonplanar(p,a.snapped))a.nonplanar+=p.number;
        if(p.group !in a.groups)a.groups+=p.group
    };
    if(a.added>0)a.groups+="fill";
    for(i in 1 until a.representatives.size)a.merged.getOrPut(a.representatives[i]) {
        mutableListOf()
    }
    +=i;
    return a
}
private fun summary(a: Analysis,out: MutableList<String>) {
    val s=a.source;
    val sizes=s.polygons.groupingBy {
        it.v.size
    }.eachCount().toSortedMap();
    val reasons=a.removed.groupingBy {
        it.reason
    }.eachCount();
    val merged=(1 until a.representatives.size).count {
        a.representatives[it]!=it
    };
    out+=listOf("[summary]","lines ${s.lines}","vertices ${s.vertices.size-1}","polygons ${s.polygons.size}",
        "errors ${s.errors.size}","ignored ${s.ignored}","nonplanar_polygons ${a.nonplanar.size}");
    for((size,n) in sizes)out+="polygon_size $size $n";
    out+=listOf("triangles ${a.triangles.size}","snapped ${a.changes.size}","merged $merged",
        "removed_repeated ${reasons.getOrDefault("repeated",0)}","removed_zero_area ${reasons.getOrDefault("zero_area",0)}",
        "removed_duplicate ${reasons.getOrDefault("duplicate",0)}","faces ${a.initial}","inconsistent_before ${a.inconsistentBefore.size}",
        "flipped_faces ${a.flipped}","outward_components ${a.outward}","boundary_loops ${a.loops.size}",
        "holes_filled ${a.loops.count{it.filled}}","fill_faces ${a.added}","final_vertices ${a.points.size-1}",
        "final_faces ${a.faces.size}","components ${a.components.size}","solids ${a.components.count{it.solid}}",
        "total_area ${Measure.real(Measure.area(a.faces,a.points))}","total_volume ${Measure.fraction(a.components.filter{it.solid}.sumOf{it.volume},6)}")
}
private fun cleanup(a: Analysis,out: MutableList<String>) {
    out+=listOf("[cleanup]","snapped ${a.changes.size}");
    for(s in a.changes)out+="snap ${s.number} ${s.before} to ${s.after}";
    out+="merged ${(1 until a.representatives.size).count{a.representatives[it]!=it}}";
    for((r,members) in a.merged)if(members.size>1)out+="merge ${a.renumber[r]?.toString()?:"-"} ${listing(members)}";
    out+="removed ${a.removed.size}";
    for(r in a.removed)out+="remove ${r.face.triangle} polygon ${r.face.polygon} line ${r.face.line} ${r.reason}"
}
private fun components(a: Analysis,out: MutableList<String>) {
    for(d in a.components) {
        val c=d.c;
        val groups=a.groups.filter {
            g->c.faces.any {
                a.faces[it-1].group==g
            }
        };
        out+=listOf("[component ${c.number}]","groups ${listing(groups)}","faces ${c.faces.size}",
            "vertices ${c.vertices.size}","edges ${c.edges.size}","boundary_edges ${c.boundary.size}",
            "nonmanifold_edges ${c.nonmanifold.size}","nonmanifold_vertices ${c.nonmanifoldVertices.size}",
            "boundary_loops ${d.loops}","closed ${yes(d.closed)}","manifold ${yes(d.manifold)}",
            "orientable ${yes(d.orientable)}","consistent ${yes(d.consistent)}","solid ${yes(d.solid)}",
            "euler ${d.euler}",if(d.genus!=null)"genus ${d.genus}" else if(d.crosscaps!=null)"crosscaps ${d.crosscaps}" else "genus -",
            "volume ${if(d.solid)Measure.fraction(d.volume,6) else "-"}","area ${Measure.real(d.area)}",
            "normal_sum ${d.normal}","bbox ${d.bbox.joinToString(" ")}","inside ${listing(d.inside)}",
            "centroid ${d.centroid}");
        for(key in listOf("convex","concave","flat"))out+="$key ${d.shapes.getOrDefault(key,0)}";
        for(key in listOf("acute","right","obtuse"))out+="$key ${d.angles.getOrDefault(key,0)}";
        out+="edge_len2 ${d.edgeMin} ${d.edgeMax}";
        out+="valence ${d.valenceMin} ${d.valenceMax}"
    }
}
private fun groups(a: Analysis,out: MutableList<String>) {
    for(g in a.groups) {
        val p=a.source.polygons.filter {
            it.group==g
        };
        val ids=a.faces.indices.filter {
            a.faces[it].group==g
        };
        out+=listOf("[group $g]","polygons ${p.size}","triangles ${a.triangles.count{it.group==g}}",
            "nonplanar ${p.count{it.number in a.nonplanar}}","faces ${ids.size}","area ${Measure.real(Measure.area(ids.map{a.faces[it]},a.points))}",
            "components ${listing(ids.map{a.mesh.faceComponent[it+1]}.toSortedSet())}")
    }
}
private fun contacts(a: Analysis,out: MutableList<String>) {
    out+="[contacts]";
    for(i in a.components.indices)for(j in i+1 until a.components.size) {
        val f=a.components[i];
        val g=a.components[j];
        if((0..2).any {
            f.bbox[it]>g.bbox[it+3]||g.bbox[it]>f.bbox[it+3]
        })continue;
        val shared=f.c.vertices.count {
            it in g.c.vertices
        };
        var gap=Long.MAX_VALUE;
        for(u in f.c.vertices)for(v in g.c.vertices)if(u!=v)gap=minOf(gap,Measure.length(Topology.edge(u,v),a.points));
        out+="contact ${f.c.number} ${g.c.number} shared $shared gap2 $gap"
    }
}
private fun kind(n: Int)=if(n==1)"boundary" else if(n==2)"manifold" else "nonmanifold"
private fun edges(a: Analysis,out: MutableList<String>) {
    val counts=mutableMapOf<String,Int>();
    var maxFaces=0;
    var shortest: Topology.Edge?=null;
    var longest: Topology.Edge?=null;
    var min=Long.MAX_VALUE;
    var max=-1L;
    for((e,ids) in a.mesh.edges) {
        increment(counts,kind(ids.size));
        increment(counts,shape(e,a));
        maxFaces=maxOf(maxFaces,ids.size);
        val length=Measure.length(e,a.points);
        if(length<min) {
            min=length;
            shortest=e
        };
        if(length>max) {
            max=length;
            longest=e
        }
    };
    out+=listOf("[edges]","edges ${a.mesh.edges.size}","boundary ${counts.getOrDefault("boundary",0)}",
        "manifold ${counts.getOrDefault("manifold",0)}","nonmanifold ${counts.getOrDefault("nonmanifold",0)}",
        "max_faces $maxFaces");
    for(key in listOf("convex","concave","flat","inconsistent"))out+="$key ${counts.getOrDefault(key,0)}";
    out+="shortest $shortest len2 $min";
    out+="longest $longest len2 $max"
}
private fun valence(a: Analysis,out: MutableList<String>) {
    val degrees=a.mesh.neighbors.values.map {
        it.size
    };
    val histogram=degrees.groupingBy {
        it
    }.eachCount().toSortedMap();
    out+=listOf("[valence]","used ${degrees.size}","isolated ${a.points.size-1-degrees.size}",
        "min ${degrees.min()}","max ${degrees.max()}","mean ${Measure.fraction(degrees.sumOf{it.toLong()},degrees.size.toLong())}");
    for((d,n) in histogram)out+="degree $d $n"
}
private fun query(w: List<String>,a: Analysis): String {
    val queryKind=w[0];
    val x=w[1].toInt();
    var prefix="$queryKind $x";
    val nv=a.points.lastIndex
    if(queryKind=="vertex") {
        if(x !in 1..nv)return "$prefix invalid";
        val ids=a.faces.indices.filter {
            x in a.faces[it].v
        };
        val boundary=a.mesh.edges.any {
            (e,f)->(e.a==x||e.b==x)&&f.size==1
        };
        return "$prefix at ${a.points[x]} faces ${ids.size} valence ${a.mesh.neighbors[x]?.size?:0} fans ${a.mesh.fans[x]?.size?:0} boundary ${yes(boundary)} components ${listing(ids.map{a.mesh.faceComponent[it+1]}.toSortedSet())}"
    }
    if(queryKind=="face") {
        if(x !in 1..a.faces.size)return "$prefix invalid";
        val f=a.faces[x-1];
        val neighbors=(0..2).map {
            k->val ids=a.mesh.edges.getValue(Topology.edge(f.v[k],f.v[(k+1)%3]));
            if(ids.size==1)"-" else if(ids.size>=3)"*" else ids.first {
                it!=x
            }.toString()
        };
        return "$prefix vertices ${f.v.joinToString(" ")} group ${f.group} polygon ${if(f.polygon==0)"-" else f.polygon.toString()} line ${if(f.line==0)"-" else f.line.toString()} component ${a.mesh.faceComponent[x]} normal ${Measure.normal(f,a.points)} area ${Measure.real(Measure.area(listOf(f),a.points))} neighbors ${listing(neighbors)}"
    }
    val y=w[2].toInt();
    if(queryKind=="edge") {
        val e=Topology.edge(x,y);
        prefix="edge $e";
        val ids=a.mesh.edges[e]?:return "$prefix none";
        return "$prefix faces ${listing(ids)} kind ${kind(ids.size)} shape ${shape(e,a)} len2 ${Measure.length(e,a.points)}"
    }
    if(queryKind=="path") {
        prefix+=" $y";
        if(x !in 1..nv||y !in 1..nv)return "$prefix invalid";
        val parent=IntArray(nv+1) {
            -1
        };
        parent[x]=0;
        val queue=ArrayDeque<Int>();
        queue.addLast(x);
        while(queue.isNotEmpty()) {
            val v=queue.removeFirst();
            for(n in a.mesh.neighbors[v].orEmpty())if(parent[n]==-1) {
                parent[n]=v;
                queue.addLast(n)
            }
        };
        if(parent[y]==-1)return "$prefix none";
        val path=mutableListOf<Int>();
        var n=y;
        while(n!=0) {
            path+=n;
            n=parent[n]
        };
        path.reverse();
        return "$prefix hops ${path.size-1} vertices ${listing(path)}"
    }
    val z=w[3].toLong();
    val point=Measure.Vec(x.toLong(),y.toLong(),z);
    prefix="$queryKind $point";
    if(queryKind=="point") {
        val inside=mutableListOf<Int>();
        var sum=0;
        for(d in a.components)if(d.solid) {
            val winding=Measure.winding(d.c.faces,a.faces,a.points,point);
            if(winding!=0) {
                inside+=d.c.number;
                sum+=winding
            }
        };
        return "$prefix inside ${listing(inside)} winding $sum"
    }
    val scores=a.faces.map {
        Measure.dot(Measure.normal(it,a.points),point)
    };
    val silhouette=a.mesh.edges.values.count {
        it.size==2&&((scores[it[0]-1]>0&&scores[it[1]-1]<0)||(scores[it[0]-1]<0&&scores[it[1]-1]>0))
    };
    return "$prefix front ${scores.count{it>0}} back ${scores.count{it<0}} side ${scores.count{it==0L}} silhouette $silhouette"
}
private fun boundaries(a: Analysis): List<String> {
    val out=mutableListOf("loops ${a.loops.size}");
    for(l in a.loops)out+="loop ${l.number} component ${l.component} length ${l.length} ${l.kind} ${if(l.filled)"filled" else "kept"} vertices ${listing(l.vertices)}";
    val nonmanifold=a.before.edges.filterValues {
        it.size>=3
    };
    out+="nonmanifold_edges ${nonmanifold.size}";
    for((e,ids) in nonmanifold)out+="edge $e faces ${listing(ids)}";
    out+="nonmanifold_vertices ${a.before.nonmanifoldVertices.size}";
    for(v in a.before.nonmanifoldVertices) {
        val fans=a.before.fans.getValue(v);
        out+="vertex $v fans ${fans.size} components ${listing(fans.flatten().map{a.before.faceComponent[it]}.toSortedSet())}"
    };
    out+="inconsistent_edges ${a.inconsistentAfter.size}";
    for(e in a.inconsistentAfter)out+="edge $e faces ${listing(a.before.edges.getValue(e))}";
    return out
}
private fun write(name: String,lines: List<String>) {
    File("output/$name").writeText(lines.joinToString("\n",postfix="\n"),Charsets.US_ASCII)
}
fun main() {
    val a=analyze(ObjIo.read(),settings());
    File("output").mkdirs();
    val out=mutableListOf<String>();
    for(section in a.settings.sections)when(section) {
        "summary"->summary(a,out);
        "warnings"-> {
            out+="[warnings]";
            for(e in a.source.errors)out+="line ${e.line} ${e.kind}"
        };
        "cleanup"->cleanup(a,out);
        "components"->components(a,out);
        "groups"->groups(a,out);
        "contacts"->contacts(a,out);
        "edges"->edges(a,out);
        "valence"->valence(a,out);
        "queries"-> {
            out+="[queries]";
            for(w in a.settings.queries)out+=query(w,a)
        }
    };
    write("report.txt",out);
    val csv=mutableListOf("component,faces,vertices,closed,euler,genus,volume6,area");
    for(d in a.components)csv+="${d.c.number},${d.c.faces.size},${d.c.vertices.size},${yes(d.closed)},${d.euler},${d.genus?.toString()?:"-"},${if(d.solid)d.volume.toString() else "-"},${Measure.real(d.area)}";
    write("components.csv",csv);
    write("boundaries.txt",boundaries(a));
    write("repaired.obj",ObjIo.repaired(a.points,a.faces))
}

import java.util.Locale
import kotlin.math.*

object Measure {
    data class Vec(val x: Long, val y: Long, val z: Long) {
        fun at(i: Int) = if(i==0)x else if(i==1)y else z
        override fun toString() = "$x $y $z"
    }
    fun subtract(a: Vec,b: Vec)=Vec(a.x-b.x,a.y-b.y,a.z-b.z)
    fun add(a: Vec,b: Vec)=Vec(a.x+b.x,a.y+b.y,a.z+b.z)
    fun cross(a: Vec,b: Vec)=Vec(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x)
    fun dot(a: Vec,b: Vec)=a.x*b.x+a.y*b.y+a.z*b.z
    fun normal(f: ObjIo.Face,p: List<Vec>)=cross(subtract(p[f.v[1]],p[f.v[0]]),subtract(p[f.v[2]],p[f.v[0]]))
    fun determinant(f: ObjIo.Face,p: List<Vec>)=dot(p[f.v[0]],cross(p[f.v[1]],p[f.v[2]]))
    fun length(e: Topology.Edge,p: List<Vec>): Long {
        val d=subtract(p[e.a],p[e.b]);
        return dot(d,d)
    }
    fun area(f: List<ObjIo.Face>,p: List<Vec>): Double {
        var total=0.0;
        for(face in f) {
            val n=normal(face,p);
            total+=sqrt(dot(n,n).toDouble())
        };
        return total/2
    }
    fun volume(ids: List<Int>,f: List<ObjIo.Face>,p: List<Vec>): Long {
        var sum=0L;
        for(i in ids)sum+=determinant(f[i-1],p);
        return sum
    }
    fun fraction(numerator: Long,denominator: Long): String {
        var n=numerator;
        var d=denominator;
        if(d<0) {
            n=-n;
            d=-d
        };
        var a=abs(n);
        var b=d;
        while(b!=0L) {
            val remainder=a%b;
            a=b;
            b=remainder
        };
        n/=a;
        d/=a;
        return if(d==1L)n.toString() else "$n/$d"
    }
    fun real(value: Double)=String.format(Locale.ROOT,"%.3f",if(value==0.0)0.0 else value)
    fun centroid(ids: List<Int>,f: List<ObjIo.Face>,p: List<Vec>,volume: Long): String = (0..2).joinToString(" ") {
        axis->var sum=0L;
        for(i in ids) {
            val face=f[i-1];
            var coordinates=0L;
            for(v in face.v)coordinates+=p[v].at(axis);
            sum+=determinant(face,p)*coordinates
        };
        fraction(sum,4*volume)
    }
    fun angle(f: ObjIo.Face,p: List<Vec>): String {
        var minimum=Long.MAX_VALUE;
        for(k in 0..2) {
            val a=p[f.v[k]];
            val b=p[f.v[(k+1)%3]];
            val c=p[f.v[(k+2)%3]];
            minimum=min(minimum,dot(subtract(b,a),subtract(c,a)))
        };
        return if(minimum<0)"obtuse" else if(minimum==0L)"right" else "acute"
    }
    fun winding(ids: List<Int>,f: List<ObjIo.Face>,p: List<Vec>,point: Vec): Int {
        var total=0.0;
        for(i in ids) {
            val v=f[i-1].v;
            val a=subtract(p[v[0]],point);
            val b=subtract(p[v[1]],point);
            val c=subtract(p[v[2]],point);
            val la=sqrt(dot(a,a).toDouble());
            val lb=sqrt(dot(b,b).toDouble());
            val lc=sqrt(dot(c,c).toDouble());
            val denominator=la*lb*lc+dot(a,b)*lc+dot(b,c)*la+dot(c,a)*lb;
            total+=2*atan2(dot(a,cross(b,c)).toDouble(),denominator)
        };
        return (total/(4*PI)).roundToInt()
    }
    fun bbox(ids: Collection<Int>,p: List<Vec>): LongArray {
        val box=longArrayOf(Long.MAX_VALUE,Long.MAX_VALUE,Long.MAX_VALUE,Long.MIN_VALUE,Long.MIN_VALUE,Long.MIN_VALUE);
        for(i in ids)for(k in 0..2) {
            box[k]=min(box[k],p[i].at(k));
            box[k+3]=max(box[k+3],p[i].at(k))
        };
        return box
    }
}

import java.io.File

object ObjIo {
    data class Polygon(val number: Int,val line: Int,val group: String,val v: IntArray)
    data class Error(val line: Int,val kind: String)
    data class Face(val triangle: Int,val polygon: Int,val line: Int,val group: String,val v: IntArray) {
        fun duplicate()=copy(v=v.copyOf())
    }
    class Model {
        var lines=0;
        var ignored=0;
        val vertices=mutableListOf(Measure.Vec(0,0,0));
        val polygons=mutableListOf<Polygon>();
        val errors=mutableListOf<Error>()
    }
    private val integer=Regex("-?[0-9]+")
    fun read(): Model {
        val m=Model();
        var group="default";
        val lines=File("input/model.obj").readLines(Charsets.US_ASCII);
        m.lines=lines.size
        for((i,text) in lines.withIndex()) {
            if(text.isEmpty()||text.startsWith("#"))continue;
            val w=text.split(' ')
            when(w[0]) {
                "v"->if(w.size!=4||w.drop(1).any {
                    !integer.matches(it)
                })m.errors+=Error(i+1,"bad_vertex") else m.vertices+=Measure.Vec(w[1].toLong(),w[2].toLong(),w[3].toLong())
                "f"-> {
                    if(w.size<4) {
                        m.errors+=Error(i+1,"short_face");
                        continue
                    };
                    val v=IntArray(w.size-1);
                    var error: String?=null
                    for(j in 1 until w.size) {
                        val word=w[j].substringBefore('/');
                        if(!integer.matches(word)) {
                            error="bad_index";
                            break
                        };
                        var number=word.toLongOrNull();
                        if(number==null) {
                            error="out_of_range";
                            break
                        };
                        if(number==0L) {
                            error="bad_index";
                            break
                        };
                        if(number<0)number+=m.vertices.size;
                        if(number<1||number>=m.vertices.size) {
                            error="out_of_range";
                            break
                        };
                        v[j-1]=number.toInt()
                    }
                    if(error!=null)m.errors+=Error(i+1,error) else m.polygons+=Polygon(m.polygons.size+1,i+1,group,v)
                }
                "g"->group=if(w.size>1)w[1] else "default"
                "vt","vn","s","o","usemtl","mtllib"->m.ignored++
                else->m.errors+=Error(i+1,"unknown_keyword")
            }
        };
        return m
    }
    fun repaired(p: List<Measure.Vec>,f: List<Face>): List<String> {
        val lines=mutableListOf("# vertices ${p.size-1} faces ${f.size}");
        for(i in 1 until p.size)lines+="v ${p[i]}";
        var previous="";
        for(face in f) {
            if(face.group!=previous) {
                lines+="g ${face.group}";
                previous=face.group
            };
            lines+="f ${face.v.joinToString(" ")}"
        };
        return lines
    }
}

object Orientation {
    fun directed(f: ObjIo.Face,a: Int,b: Int)=(0..2).any {
        f.v[it]==a&&f.v[(it+1)%3]==b
    }
    fun flip(f: ObjIo.Face) {
        val t=f.v[1];
        f.v[1]=f.v[2];
        f.v[2]=t
    }
    fun inconsistent(faces: List<ObjIo.Face>,edges: Map<Topology.Edge,List<Int>>): List<Topology.Edge> = edges.filter {
        (e,ids)->ids.size==2&&directed(faces[ids[0]-1],e.a,e.b)==directed(faces[ids[1]-1],e.a,e.b)
    }.keys.toList()
    fun repair(faces: List<ObjIo.Face>,edges: Map<Topology.Edge,List<Int>>) {
        val visited=BooleanArray(faces.size+1);
        for(seed in 1..faces.size) {
            if(visited[seed])continue;
            visited[seed]=true;
            val queue=ArrayDeque<Int>();
            queue.addLast(seed);
            while(queue.isNotEmpty()) {
                val current=queue.removeFirst();
                val f=faces[current-1];
                for(k in 0..2) {
                    val a=f.v[k];
                    val b=f.v[(k+1)%3];
                    val ids=edges.getValue(Topology.edge(a,b));
                    if(ids.size!=2)continue;
                    val other=if(ids[0]==current)ids[1] else ids[0];
                    if(visited[other])continue;
                    if(directed(faces[other-1],a,b))flip(faces[other-1]);
                    visited[other]=true;
                    queue.addLast(other)
                }
            }
        }
    }
    fun orientable(faces: List<ObjIo.Face>,mesh: Topology.Mesh): BooleanArray {
        val copied=faces.map {
            it.duplicate()
        };
        repair(copied,mesh.edges);
        val result=BooleanArray(mesh.components.size+1) {
            true
        };
        for(e in inconsistent(copied,mesh.edges))result[mesh.faceComponent[mesh.edges.getValue(e)[0]]]=false;
        return result
    }
}

object Repair {
    data class Snap(val number: Int,val before: Measure.Vec,val after: Measure.Vec)
    data class Removed(val face: ObjIo.Face,val reason: String)
    fun split(polygons: List<ObjIo.Polygon>): List<ObjIo.Face> {
        val result=mutableListOf<ObjIo.Face>();
        for(p in polygons)for(i in 1 until p.v.size-1)result+=ObjIo.Face(result.size+1,p.number,p.line,p.group,intArrayOf(p.v[0],p.v[i],p.v[i+1]));
        return result
    }
    fun snap(vertices: List<Measure.Vec>,spacing: Int,changes: MutableList<Snap>): List<Measure.Vec> {
        val result=mutableListOf(vertices[0]);
        for(i in 1 until vertices.size) {
            val p=vertices[i];
            val q=Measure.Vec(spacing*Math.floorDiv(2*p.x+spacing,2L*spacing),spacing*Math.floorDiv(2*p.y+spacing,
                2L*spacing),spacing*Math.floorDiv(2*p.z+spacing,2L*spacing));
            result+=q;
            if(p!=q)changes+=Snap(i,p,q)
        };
        return result
    }
    fun representatives(points: List<Measure.Vec>,merge: Boolean): IntArray {
        val owner=mutableMapOf<Measure.Vec,Int>();
        return IntArray(points.size) {
            i->if(i==0)0 else if(merge)owner.getOrPut(points[i]) {
                i
            } else i
        }
    }
    fun clean(triangles: List<ObjIo.Face>,points: List<Measure.Vec>,representatives: IntArray,
        zero: Boolean,duplicate: Boolean,removed: MutableList<Removed>): MutableList<ObjIo.Face> {
        val result=mutableListOf<ObjIo.Face>();
        val seen=mutableSetOf<List<Int>>();
        for(t in triangles) {
            val f=t.copy(v=t.v.map {
                representatives[it]
            }.toIntArray());
            var reason: String?=null;
            if(f.v.toSet().size<3)reason="repeated" else if(zero&&Measure.normal(f,points)==Measure.Vec(0,0,0))reason="zero_area";
            if(reason==null) {
                val key=f.v.sorted();
                if(duplicate&&key in seen)reason="duplicate" else seen+=key
            };
            if(reason!=null)removed+=Removed(t,reason) else result+=f
        };
        return result
    }
    fun fill(faces: MutableList<ObjIo.Face>,loops: List<Topology.Loop>,maximum: Int,permitted: Set<Int>): Int {
        var count=0;
        for(l in loops) {
            if(l.kind!="coherent"||l.length !in 3..maximum||l.vertices.toSet().size!=l.length||l.component !in permitted)continue;
            l.filled=true;
            for(i in 2 until l.length) {
                faces+=ObjIo.Face(0,0,0,"fill",intArrayOf(l.vertices[0],l.vertices[i],l.vertices[i-1]));
                count++
            }
        };
        return count
    }
}

import java.util.TreeMap
import java.util.TreeSet

object Topology {
    data class Edge(val a: Int,val b: Int): Comparable<Edge> {
        override fun compareTo(other: Edge): Int {
            val c=a.compareTo(other.a);
            return if(c!=0)c else b.compareTo(other.b)
        }
        override fun toString()="$a $b"
    }
    fun edge(a: Int,b: Int)=Edge(minOf(a,b),maxOf(a,b))
    class Component(val number: Int,val faces: List<Int>) {
        val vertices=sortedSetOf<Int>();
        val edges=mutableListOf<Edge>();
        val boundary=mutableListOf<Edge>();
        val nonmanifold=mutableListOf<Edge>();
        val nonmanifoldVertices=mutableListOf<Int>()
    }
    class Mesh(val faceComponent: IntArray) {
        val edges=sortedMapOf<Edge,MutableList<Int>>();
        val components=mutableListOf<Component>();
        val fans=sortedMapOf<Int,List<List<Int>>>();
        val nonmanifoldVertices=mutableListOf<Int>();
        val neighbors=sortedMapOf<Int,java.util.SortedSet<Int>>()
    }
    fun parts(remaining: java.util.SortedSet<Int>,neighbors: Map<Int,java.util.SortedSet<Int>>): List<List<Int>> {
        val result=mutableListOf<List<Int>>();
        while(remaining.isNotEmpty()) {
            val seed=remaining.first();
            remaining.remove(seed);
            val queue=ArrayDeque<Int>();
            queue.addLast(seed);
            val part=mutableListOf<Int>();
            while(queue.isNotEmpty()) {
                val f=queue.removeFirst();
                part+=f;
                for(n in neighbors[f].orEmpty())if(remaining.remove(n))queue.addLast(n)
            };
            result+=part.sorted()
        };
        return result
    }
    fun analyze(faces: List<ObjIo.Face>): Mesh {
        val mesh=Mesh(IntArray(faces.size+1));
        val adjacency=mutableMapOf<Int,java.util.SortedSet<Int>>();
        val remaining=sortedSetOf<Int>()
        for(i in 1..faces.size) {
            remaining+=i;
            adjacency[i]=sortedSetOf();
            val v=faces[i-1].v;
            for(k in 0..2)mesh.edges.getOrPut(edge(v[k],v[(k+1)%3])) {
                mutableListOf()
            }
            +=i
        }
        for((e,ids) in mesh.edges) {
            mesh.neighbors.getOrPut(e.a) {
                sortedSetOf()
            }
            +=e.b;
            mesh.neighbors.getOrPut(e.b) {
                sortedSetOf()
            }
            +=e.a;
            for(i in ids)adjacency.getValue(i).addAll(ids)
        }
        for(ids in parts(remaining,adjacency)) {
            val c=Component(mesh.components.size+1,ids);
            for(i in ids) {
                mesh.faceComponent[i]=c.number;
                c.vertices.addAll(faces[i-1].v.toList())
            };
            for((e,adjacent) in mesh.edges)if(adjacent[0] in ids) {
                c.edges+=e;
                if(adjacent.size==1)c.boundary+=e;
                if(adjacent.size>=3)c.nonmanifold+=e
            };
            mesh.components+=c
        }
        for(v in mesh.neighbors.keys) {
            val links=mutableMapOf<Int,java.util.SortedSet<Int>>();
            val incident=sortedSetOf<Int>();
            for(i in 1..faces.size)if(v in faces[i-1].v) {
                incident+=i;
                links[i]=sortedSetOf()
            };
            for((e,ids) in mesh.edges)if(e.a==v||e.b==v)for(i in ids)links.getValue(i).addAll(ids);
            val fans=parts(incident,links);
            mesh.fans[v]=fans;
            if(fans.size>=2)mesh.nonmanifoldVertices+=v
        }
        for(c in mesh.components)for(v in c.vertices)if(mesh.fans.getValue(v).count {
            mesh.faceComponent[it[0]]==c.number
        }
        >=2)c.nonmanifoldVertices+=v
        return mesh
    }
    class Loop(val number: Int,val component: Int,val length: Int,val kind: String,val vertices: MutableList<Int>) {
        var filled=false
    }
    fun loops(faces: List<ObjIo.Face>,mesh: Mesh): List<Loop> {
        val result=mutableListOf<Loop>();
        for(c in mesh.components) {
            val unused=TreeSet(c.boundary);
            while(unused.isNotEmpty()) {
                val first=unused.first();
                unused.remove(first);
                val sequence=mutableListOf(first.a,first.b);
                var current=first.b
                while(current!=first.a) {
                    var chosen: Edge?=null;
                    var other=Int.MAX_VALUE;
                    for(e in unused) {
                        val n=if(e.a==current)e.b else if(e.b==current)e.a else Int.MAX_VALUE;
                        if(n<other) {
                            other=n;
                            chosen=e
                        }
                    };
                    if(chosen==null)break;
                    unused.remove(chosen);
                    sequence+=other;
                    current=other
                }
                var kind="open";
                var length=sequence.size-1;
                if(current==first.a) {
                    sequence.removeAt(sequence.lastIndex);
                    length=sequence.size;
                    var forward=0;
                    for(i in 0 until length) {
                        val a=sequence[i];
                        val b=sequence[(i+1)%length];
                        val f=mesh.edges.getValue(edge(a,b))[0];
                        if(Orientation.directed(faces[f-1],a,b))forward++
                    };
                    kind=if(forward==0||forward==length)"coherent" else "mixed";
                    if(forward==0)sequence.subList(1,sequence.size).reverse()
                };
                result+=Loop(result.size+1,c.number,length,kind,sequence)
            }
        };
        return result
    }
}
